import re, math, sqlite3
from collections import Counter, defaultdict
from pymongo import MongoClient

client=MongoClient('mongodb://dab-mongo:27017')
articles=list(client.articles_db.articles.find({}, {'_id':0,'article_id':1,'title':1,'description':1}).sort('article_id',1))
client.close()
print('loaded', len(articles), flush=True)

def tokenize(s):
    return re.findall(r"[a-z0-9]+(?:[.'-][a-z0-9]+)?", s.lower())

def make_terms(words):
    uni=set(); bi=set(); tri=set()
    for w in words:
        ts=tokenize(w)
        if len(ts)==1: uni.add(ts[0])
        elif len(ts)==2: bi.add(tuple(ts))
        elif len(ts)==3: tri.add(tuple(ts))
